-- 읽기 전용: 운영 DB의 구조(표·열·제약·색인·보기·함수·트리거·정책·권한)만 조회한다. 데이터 행은 읽지 않는다.
-- 목적(대표 2026-11-26 기반 스키마 지시): 격리 인증 시험 DB의 기반 스키마를 운영 구조와 대조해 만든다. 기존 ops-run-sql 조회 경로(읽기 전용 트랜잭션)로만 실행.
-- 각 문장은 JSON 한 줄을 돌려준다(`kind` 칸으로 구분).
\pset tuples_only on
\pset format unaligned
select jsonb_build_object('kind','env','extensions',(select jsonb_agg(extname order by extname) from pg_catalog.pg_extension),'schemas',(select jsonb_agg(nspname order by nspname) from pg_catalog.pg_namespace where nspname not like 'pg_%' and nspname <> 'information_schema'),'publications',(select jsonb_agg(jsonb_build_object('pub',pubname,'tables',(select jsonb_agg(schemaname||'.'||tablename order by tablename) from pg_catalog.pg_publication_tables t where t.pubname=p.pubname)) order by pubname) from pg_catalog.pg_publication p))::text;
select jsonb_build_object('kind','tables','rows',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','storage') and c.relkind in ('r','p','v','m')))::text;
select jsonb_build_object('kind','columns','rows',(select jsonb_agg(jsonb_build_object('t',table_name,'c',column_name,'n',ordinal_position,'type',data_type,'udt',udt_name,'len',character_maximum_length,'null',is_nullable,'def',column_default,'ident',is_identity,'gen',generation_expression) order by table_name,ordinal_position) from information_schema.columns where table_schema='public'))::text;
select jsonb_build_object('kind','constraints','rows',(select jsonb_agg(jsonb_build_object('t',tc.table_name,'name',tc.constraint_name,'type',tc.constraint_type,'cols',(select jsonb_agg(k.column_name order by k.ordinal_position) from information_schema.key_column_usage k where k.constraint_schema=tc.constraint_schema and k.constraint_name=tc.constraint_name and k.table_name=tc.table_name),'check',(select cc.check_clause from information_schema.check_constraints cc where cc.constraint_schema=tc.constraint_schema and cc.constraint_name=tc.constraint_name),'ref',(select jsonb_build_object('table',u.table_name,'cols',(select jsonb_agg(x.column_name order by x.ordinal_position) from information_schema.key_column_usage x where x.constraint_schema=r.unique_constraint_schema and x.constraint_name=r.unique_constraint_name),'del',r.delete_rule,'upd',r.update_rule) from information_schema.referential_constraints r join information_schema.table_constraints u on u.constraint_schema=r.unique_constraint_schema and u.constraint_name=r.unique_constraint_name where r.constraint_schema=tc.constraint_schema and r.constraint_name=tc.constraint_name limit 1)) order by tc.table_name,tc.constraint_name) from information_schema.table_constraints tc where tc.table_schema='public' and tc.constraint_type in ('PRIMARY KEY','UNIQUE','FOREIGN KEY','CHECK') and tc.constraint_name not like '%_not_null'))::text;
select jsonb_build_object('kind','indexes','rows',(select jsonb_agg(jsonb_build_object('t',tablename,'name',indexname,'def',indexdef) order by tablename,indexname) from pg_catalog.pg_indexes where schemaname='public'))::text;
select jsonb_build_object('kind','views','rows',(select jsonb_agg(jsonb_build_object('name',table_name,'def',view_definition) order by table_name) from information_schema.views where table_schema='public'))::text;
select jsonb_build_object('kind','routines','rows',(select jsonb_agg(jsonb_build_object('schema',r.routine_schema,'name',r.routine_name,'specific',r.specific_name,'type',r.routine_type,'returns',r.data_type,'lang',r.external_language,'security',r.security_type,'volatile',r.is_deterministic,'body',r.routine_definition,'config',(select a.proconfig from pg_catalog.pg_proc a where a.oid=(reverse(split_part(reverse(r.specific_name),'_',1)))::oid),'params',(select jsonb_agg(jsonb_build_object('n',p.parameter_name,'type',p.data_type,'udt',p.udt_name,'mode',p.parameter_mode,'def',p.parameter_default) order by p.ordinal_position) from information_schema.parameters p where p.specific_schema=r.specific_schema and p.specific_name=r.specific_name)) order by r.routine_schema,r.routine_name,r.specific_name) from information_schema.routines r where r.routine_schema in ('public','ingest_private','location_private','dedupe_private','map_private') or r.routine_schema not in ('pg_catalog','information_schema','extensions','auth','storage','graphql','graphql_public','realtime','vault','net','cron','pgsodium','pgsodium_masks','supabase_functions','supabase_migrations','pgbouncer')))::text;
select jsonb_build_object('kind','triggers','rows',(select jsonb_agg(jsonb_build_object('schema',event_object_schema,'t',event_object_table,'name',trigger_name,'event',event_manipulation,'timing',action_timing,'orient',action_orientation,'cond',action_condition,'stmt',action_statement) order by event_object_schema,event_object_table,trigger_name,event_manipulation) from information_schema.triggers where event_object_schema in ('public','auth','storage')))::text;
select jsonb_build_object('kind','policies','rows',(select jsonb_agg(jsonb_build_object('schema',schemaname,'t',tablename,'name',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'using',qual,'check',with_check) order by schemaname,tablename,policyname) from pg_catalog.pg_policies where schemaname in ('public','storage')))::text;
select jsonb_build_object('kind','grants','tables',(select jsonb_agg(jsonb_build_object('t',table_name,'g',grantee,'p',privilege_type) order by table_name,grantee,privilege_type) from information_schema.table_privileges where table_schema='public' and grantee in ('anon','authenticated','service_role','public')),'columns',(select jsonb_agg(jsonb_build_object('t',table_name,'c',column_name,'g',grantee,'p',privilege_type) order by table_name,column_name,grantee,privilege_type) from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated','service_role','public')),'routines',(select jsonb_agg(jsonb_build_object('s',specific_name,'r',routine_name,'g',grantee,'p',privilege_type) order by routine_name,grantee) from information_schema.routine_privileges where routine_schema in ('public','ingest_private','location_private','dedupe_private','map_private') and grantee in ('anon','authenticated','service_role','public')))::text;
select jsonb_build_object('kind','sequences_types','sequences',(select jsonb_agg(jsonb_build_object('name',sequence_name,'type',data_type) order by sequence_name) from information_schema.sequences where sequence_schema='public'),'enums',(select jsonb_agg(jsonb_build_object('type',t.typname,'labels',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_catalog.pg_enum e where e.enumtypid=t.oid)) order by t.typname) from pg_catalog.pg_type t join pg_catalog.pg_namespace n on n.oid=t.typnamespace where t.typtype='e' and n.nspname='public'))::text;
